// ServerInterface represents all server handlers.
type ServerInterface interface {
	// RenewCert Renew the agent certificate
	// (POST /cert/renew)
	RenewCert(w http.ResponseWriter, r *http.Request)
	// EnrollFinish Enrollment steps 4 to 5
	// (POST /enroll/finish)
	EnrollFinish(w http.ResponseWriter, r *http.Request)
	// GetEnrollResult Result of a pending enrollment
	// (GET /enroll/result)
	GetEnrollResult(w http.ResponseWriter, r *http.Request)
	// EnrollStart Enrollment steps 2 to 3
	// (POST /enroll/start)
	EnrollStart(w http.ResponseWriter, r *http.Request)
	// UploadK8sInventory Scanner: inventory of one cluster
	// (POST /k8s/inventory)
	UploadK8sInventory(w http.ResponseWriter, r *http.Request)
	// Poll Report status and wait for directives
	// (POST /poll)
	Poll(w http.ResponseWriter, r *http.Request)
	// DownloadProbe Scanner: signed probe binary of the deployed version
	// (GET /probe/{os}/{arch})
	DownloadProbe(w http.ResponseWriter, r *http.Request, os TargetOs, arch TargetArch)
	// UploadReport Upload a collection report
	// (POST /reports)
	UploadReport(w http.ResponseWriter, r *http.Request, params UploadReportParams)
	// SubmitScanJobResult Scanner: outcome of a scan job
	// (POST /scan-jobs/{id}/result)
	SubmitScanJobResult(w http.ResponseWriter, r *http.Request, id string)
	// GetServerChain Certificate chain of the server's response signing key
	// (GET /server-chain)
	GetServerChain(w http.ResponseWriter, r *http.Request)
	// GetTrustBundle Current Agent TLS anchors and Agent CA
	// (GET /trust-bundle)
	GetTrustBundle(w http.ResponseWriter, r *http.Request)
	// DownloadUpdateBundle Download a release bundle
	// (GET /update/bundle/{version})
	DownloadUpdateBundle(w http.ResponseWriter, r *http.Request, version string, params DownloadUpdateBundleParams)
	// CheckUpdate Deployed version and its manifest for the caller's platform
	// (GET /update/check)
	CheckUpdate(w http.ResponseWriter, r *http.Request, params CheckUpdateParams)
}

