// StrictServerInterface represents all server handlers.
type StrictServerInterface interface {
	// RenewCert Renew the agent certificate
	// (POST /cert/renew)
	RenewCert(ctx context.Context, request RenewCertRequestObject) (RenewCertResponseObject, error)
	// EnrollFinish Enrollment steps 4 to 5
	// (POST /enroll/finish)
	EnrollFinish(ctx context.Context, request EnrollFinishRequestObject) (EnrollFinishResponseObject, error)
	// GetEnrollResult Result of a pending enrollment
	// (GET /enroll/result)
	GetEnrollResult(ctx context.Context, request GetEnrollResultRequestObject) (GetEnrollResultResponseObject, error)
	// EnrollStart Enrollment steps 2 to 3
	// (POST /enroll/start)
	EnrollStart(ctx context.Context, request EnrollStartRequestObject) (EnrollStartResponseObject, error)
	// UploadK8sInventory Scanner: inventory of one cluster
	// (POST /k8s/inventory)
	UploadK8sInventory(ctx context.Context, request UploadK8sInventoryRequestObject) (UploadK8sInventoryResponseObject, error)
	// Poll Report status and wait for directives
	// (POST /poll)
	Poll(ctx context.Context, request PollRequestObject) (PollResponseObject, error)
	// DownloadProbe Scanner: signed probe binary of the deployed version
	// (GET /probe/{os}/{arch})
	DownloadProbe(ctx context.Context, request DownloadProbeRequestObject) (DownloadProbeResponseObject, error)
	// UploadReport Upload a collection report
	// (POST /reports)
	UploadReport(ctx context.Context, request UploadReportRequestObject) (UploadReportResponseObject, error)
	// SubmitScanJobResult Scanner: outcome of a scan job
	// (POST /scan-jobs/{id}/result)
	SubmitScanJobResult(ctx context.Context, request SubmitScanJobResultRequestObject) (SubmitScanJobResultResponseObject, error)
	// GetServerChain Certificate chain of the server's response signing key
	// (GET /server-chain)
	GetServerChain(ctx context.Context, request GetServerChainRequestObject) (GetServerChainResponseObject, error)
	// GetTrustBundle Current Agent TLS anchors and Agent CA
	// (GET /trust-bundle)
	GetTrustBundle(ctx context.Context, request GetTrustBundleRequestObject) (GetTrustBundleResponseObject, error)
	// DownloadUpdateBundle Download a release bundle
	// (GET /update/bundle/{version})
	DownloadUpdateBundle(ctx context.Context, request DownloadUpdateBundleRequestObject) (DownloadUpdateBundleResponseObject, error)
	// CheckUpdate Deployed version and its manifest for the caller's platform
	// (GET /update/check)
	CheckUpdate(ctx context.Context, request CheckUpdateRequestObject) (CheckUpdateResponseObject, error)
}

type StrictHandlerFunc func(ctx context.Context, w http.ResponseWriter, r *http.Request, request any) (any, error)
type StrictMiddlewareFunc func(f StrictHandlerFunc, operationID string) StrictHandlerFunc

type StrictHTTPServerOptions struct {
	RequestErrorHandlerFunc  func(w http.ResponseWriter, r *http.Request, err error)
	ResponseErrorHandlerFunc func(w http.ResponseWriter, r *http.Request, err error)
}

func NewStrictHandler(ssi StrictServerInterface, middlewares []StrictMiddlewareFunc) ServerInterface {
	return &strictHandler{ssi: ssi, middlewares: middlewares, options: StrictHTTPServerOptions{
		RequestErrorHandlerFunc: func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusBadRequest)
		},
		ResponseErrorHandlerFunc: func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusInternalServerError)
		},
	}}
}

func NewStrictHandlerWithOptions(ssi StrictServerInterface, middlewares []StrictMiddlewareFunc, options StrictHTTPServerOptions) ServerInterface {
	if options.RequestErrorHandlerFunc == nil {
		options.RequestErrorHandlerFunc = func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusBadRequest)
		}
	}
	if options.ResponseErrorHandlerFunc == nil {
		options.ResponseErrorHandlerFunc = func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusInternalServerError)
		}
	}
	return &strictHandler{ssi: ssi, middlewares: middlewares, options: options}
}

type strictHandler struct {
	ssi         StrictServerInterface
	middlewares []StrictMiddlewareFunc
	options     StrictHTTPServerOptions
}

// RenewCert operation middleware
func (sh *strictHandler) RenewCert(w http.ResponseWriter, r *http.Request) {
	var request RenewCertRequestObject

	var body RenewCertJSONRequestBody
	if err := runtime.BindJSONBody(r, &body); err != nil {
		sh.options.RequestErrorHandlerFunc(w, r, fmt.Errorf("can't decode JSON body: %w", err))
		return
	}
	request.Body = &body

	handler := func(ctx context.Context, w http.ResponseWriter, r *http.Request, request interface{}) (interface{}, error) {
		return sh.ssi.RenewCert(ctx, request.(RenewCertRequestObject))
	}
	for _, middleware := range sh.middlewares {
		handler = middleware(handler, "RenewCert")
	}

	response, err := handler(r.Context(), w, r, request)

	if err != nil {
		sh.options.ResponseErrorHandlerFunc(w, r, err)
	} else if validResponse, ok := response.(RenewCertResponseObject); ok {
		if err := validResponse.VisitRenewCertResponse(w); err != nil {
			sh.options.ResponseErrorHandlerFunc(w, r, err)
		}
	} else if response != nil {
		sh.options.ResponseErrorHandlerFunc(w, r, fmt.Errorf("unexpected response type: %T", response))
	}
}

